STEP_OLD_1 = "        # Normalize the logits\n        logprobs = logits - mx.logsumexp(logits, axis=-1, keepdims=True)\n\n        # One batched call when the batch shares a sampler.\n        samplers = [\n            self.fallback_sampler if s is None else s\n            for s in (self.samplers or [None] * len(self.uids))\n        ]\n        if not samplers or all(s is samplers[0] for s in samplers):\n            sampled = (samplers[0] if samplers else self.fallback_sampler)(logprobs)\n        else:\n            sampled = mx.concatenate(\n                [s(logprobs[e : e + 1]) for e, s in enumerate(samplers)], axis=0\n            )\n\n        # Assign the next step to member variables and start computing it\n        # asynchronously\n        self._next_tokens = sampled\n        self._next_logprobs = list(logprobs)\n        mx.async_eval(self._next_tokens, self._next_logprobs, token_context)\n"

STEP_NEW_1 = "        samplers = [\n            self.fallback_sampler if s is None else s\n            for s in (self.samplers or [None] * len(self.uids))\n        ]\n        if all(s is greedy_sampler for s in samplers):\n            # Greedy fast path: argmax of the raw logits picks the same token\n            # as argmax of logits - logsumexp(logits) (a per-row constant\n            # shift), so skip the full-vocab normalization. Log-probabilities\n            # are materialized lazily only if a consumer asks for them.\n            sampled = mx.argmax(logits, axis=-1)\n            self._next_tokens = sampled\n            self._next_logprobs = [_JitLazyLogprobs(logits, e) for e in range(len(self.uids))]\n            mx.async_eval(self._next_tokens, token_context)\n        else:\n            # Normalize the logits\n            logprobs = logits - mx.logsumexp(logits, axis=-1, keepdims=True)\n\n            # One batched call when the batch shares a sampler.\n            if all(s is samplers[0] for s in samplers):\n                sampled = samplers[0](logprobs)\n            else:\n                sampled = mx.concatenate(\n                    [s(logprobs[e : e + 1]) for e, s in enumerate(samplers)], axis=0\n                )\n            self._next_tokens = sampled\n            self._next_logprobs = list(logprobs)\n            mx.async_eval(self._next_tokens, self._next_logprobs, token_context)\n"

